#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/ghcr.io-microsoft-garnet-2.2.14-arm64-oci ] || "$F" ghcr.io/microsoft/garnet sha256:52b5e51fdb637afa4e7612656e1017624e383b2d070bad2233767a561127249c ghcr.io/microsoft/garnet:2.2.14 images/ghcr.io-microsoft-garnet-2.2.14-arm64-oci
[ "$A" = arm64 ] || [ -f images/ghcr.io-microsoft-garnet-2.2.14-amd64.docker.tar ] || "$F" ghcr.io/microsoft/garnet sha256:c5f73c1ec85f260e40bb35ed3e9f10f431f1506cd95286c6063fc1675fae1ea1 ghcr.io/microsoft/garnet:2.2.14 images/ghcr.io-microsoft-garnet-2.2.14-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/ghcr.io-microsoft-garnet-2.2.14-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/ghcr.io-microsoft-garnet-2.2.14-arm64-oci
